# Homebrew Cask for Akey. Generated by akey's release workflow from
# packaging/homebrew/akey.rb in https://github.com/dosp0911/akey
#
#   brew tap dosp0911/akey && brew trust dosp0911/akey
#   brew install dosp0911/akey/akey
cask "akey" do
  version "0.3.1"
  sha256 "361140457db3220c8622a81dd1da18a7096cc0d052b4510b959ec1495ace0b70"

  url "https://github.com/dosp0911/akey/releases/download/v#{version}/akey-macos-universal.tar.gz"
  name "Akey"
  desc "Agent key: local secret store for AI agents (menu bar app + CLI, Touch ID)"
  homepage "https://github.com/dosp0911/akey"

  depends_on macos: :ventura

  app "Akey.app"
  # The app executable is also the CLI (same signature, same keychain access)
  binary "#{appdir}/Akey.app/Contents/MacOS/akey"

  # Until builds are signed with an Apple Developer ID, the quarantine flag must be removed
  installed_app = "#{appdir}/Akey.app"
  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", installed_app], must_succeed: false
  end

  uninstall quit: "local.akey"

  zap trash: [
    "~/Library/Application Support/akey",
    "~/Library/Preferences/local.akey.plist",
  ]

  caveats <<~EOS
    Secrets are stored in the 'akey' item of your login keychain and are kept when you uninstall.
    After an update, if macOS asks for your keychain password the first time Akey opens, click "Always Allow".
  EOS
end
